'orders ' + (() => {
  const vis = (e) => { const r = e.getBoundingClientRect(); if (r.width < 6 || r.height < 6 || r.bottom < 0 || r.right < 0 || r.top > innerHeight || r.left > innerWidth) return null;
    const cx = Math.min(innerWidth - 1, Math.max(0, r.left + r.width / 2)), cy = Math.min(innerHeight - 1, Math.max(0, r.top + r.height / 2)); const t = document.elementFromPoint(cx, cy); return t && (t === e || e.contains(t)) ? r : null; };
  const B = [...document.querySelectorAll('button, [role=button]')].map((e) => [e, vis(e)]).filter((x) => x[1]);
  const bad = [];
  for (let i = 0; i < B.length; i++) for (let j = i + 1; j < B.length; j++) {
    const [a, r] = B[i], [b, q] = B[j]; if (a.contains(b) || b.contains(a) || /carb/.test(a.className + ' ' + b.className)) continue;
    const ox = Math.min(r.right, q.right) - Math.max(r.left, q.left), oy = Math.min(r.bottom, q.bottom) - Math.max(r.top, q.top);
    if (ox > 8 && oy > 8) bad.push((a.className || a.tagName).toString().slice(0, 30) + ' x ' + (b.className || b.tagName).toString().slice(0, 30));
  }
  const cut = B.filter(([e, r]) => r.right > innerWidth + 1 || r.left < -1 || r.bottom > innerHeight + 1 || r.top < -1).map(([e]) => String(e.className).slice(0, 30));
  return 'OVL ' + bad.length + (bad.length ? ' ' + bad.slice(0, 5).join(' | ') : '') + ' ; CUT ' + cut.length + (cut.length ? ' ' + cut.slice(0, 4).join(' | ') : '');
})()

